/**
 * What a code means, or `undefined` for one this build does not declare.
 *
 * `undefined` rather than a throw, and rather than an invented entry: a lock
 * or a transcript from a newer build can name a code this one has never heard
 * of, and "I do not know that code" is the honest answer to it.
 */
export function explainDiagnostic(code: string): DiagnosticCodeDoc | undefined {
  return DIAGNOSTIC_CATALOGUE[code.trim().toUpperCase()];
}
